// Given: the step-through player. Do not edit this file.
//
// Replays a Recording: play, pause, step forward and back, scrub. Each frame
// shows its label, its values, and its primitives drawn over an optional
// background (for example the bodies involved).
import type { Recording } from "../trace/trace";
import { clear, drawPrims } from "../render/debugDraw";
import { palette } from "../render/colors";
import { createView, type View, type ViewOptions } from "../render/view";
import { injectStyles } from "./styles";

export type PlayerOptions = ViewOptions & {
  /** Drawn under every frame. */
  background?: (view: View) => void;
  /** Seconds per frame while playing. Default 0.8. */
  secondsPerFrame?: number;
  /** Canvas height in CSS pixels. Default 360. */
  height?: number;
};

export type Player = {
  readonly view: View;
  readonly index: number;
  /** Replace the recording (for example after a drag), keeping the position when possible. */
  setRecording(recording: Recording): void;
  goTo(index: number): void;
  play(): void;
  pause(): void;
  destroy(): void;
};

const reducedMotion = () =>
  typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

export function createPlayer(
  container: HTMLElement,
  recording: Recording,
  options: PlayerOptions = {},
): Player {
  injectStyles();
  const root = document.createElement("div");
  root.className = "pfs-player";
  root.tabIndex = 0;
  root.setAttribute("role", "group");
  root.setAttribute("aria-label", "Step-through visual. Arrow keys step, space plays.");
  root.innerHTML = `
    <canvas class="pfs-canvas" style="height:${options.height ?? 360}px"></canvas>
    <div class="pfs-caption"><span class="pfs-group"></span><span class="pfs-label"></span></div>
    <div class="pfs-controls">
      <button type="button" data-act="prev" aria-label="Previous step">&#9664;&#9664;</button>
      <button type="button" data-act="play" aria-label="Play">&#9654;</button>
      <button type="button" data-act="next" aria-label="Next step">&#9654;&#9654;</button>
      <input type="range" min="0" value="0" step="1" aria-label="Scrub through steps" />
      <span class="pfs-count"></span>
    </div>
    <dl class="pfs-values"></dl>`;
  container.appendChild(root);

  const q = <T extends Element>(sel: string) => root.querySelector(sel) as T;
  const canvas = q<HTMLCanvasElement>("canvas");
  const view = createView(canvas, options);
  const playBtn = q<HTMLButtonElement>('[data-act="play"]');
  const range = q<HTMLInputElement>('input[type="range"]');
  const groupEl = q<HTMLElement>(".pfs-group");
  const labelEl = q<HTMLElement>(".pfs-label");
  const countEl = q<HTMLElement>(".pfs-count");
  const valuesEl = q<HTMLElement>(".pfs-values");

  let rec = recording;
  let index = 0;
  let timer = 0;
  const secondsPerFrame = options.secondsPerFrame ?? 0.8;

  function render() {
    const pal = palette();
    clear(view, pal);
    options.background?.(view);
    const frame = rec.frames[index];
    if (frame) drawPrims(view, frame.prims, pal);
    const total = rec.frames.length;
    range.max = String(Math.max(0, total - 1));
    range.value = String(index);
    range.disabled = total <= 1;
    countEl.textContent = total ? `${index + 1} / ${total}` : "no steps";
    groupEl.textContent = frame && frame.group.length ? `${frame.group.join(" › ")}: ` : "";
    labelEl.textContent = frame ? frame.label : "Nothing was recorded.";
    valuesEl.replaceChildren(
      ...Object.entries(frame?.values ?? {}).flatMap(([k, v]) => {
        const dt = document.createElement("dt");
        dt.textContent = k;
        const dd = document.createElement("dd");
        dd.textContent = Number.isInteger(v) ? String(v) : v.toFixed(4);
        return [dt, dd];
      }),
    );
  }

  function goTo(i: number) {
    index = Math.max(0, Math.min(i, rec.frames.length - 1));
    render();
  }

  function pause() {
    window.clearInterval(timer);
    timer = 0;
    playBtn.innerHTML = "&#9654;";
    playBtn.setAttribute("aria-label", "Play");
  }

  function play() {
    if (rec.frames.length <= 1) return;
    if (index >= rec.frames.length - 1) goTo(0);
    window.clearInterval(timer);
    timer = window.setInterval(() => {
      if (index >= rec.frames.length - 1) pause();
      else goTo(index + 1);
    }, secondsPerFrame * 1000);
    playBtn.innerHTML = "&#10074;&#10074;";
    playBtn.setAttribute("aria-label", "Pause");
  }

  const toggle = () => (timer ? pause() : play());
  const stepBy = (d: number) => {
    pause();
    goTo(index + d);
  };

  root.addEventListener("click", (e) => {
    const act = (e.target as HTMLElement).closest("button")?.dataset.act;
    if (act === "prev") stepBy(-1);
    else if (act === "next") stepBy(1);
    else if (act === "play") toggle();
  });
  range.addEventListener("input", () => {
    pause();
    goTo(Number(range.value));
  });
  root.addEventListener("keydown", (e) => {
    if (e.target === range) return;
    const actions: Record<string, () => void> = {
      ArrowLeft: () => stepBy(-1),
      ArrowRight: () => stepBy(1),
      " ": toggle,
    };
    const action = actions[e.key];
    if (action) {
      action();
      e.preventDefault();
    }
  });

  const resize = new ResizeObserver(() => render());
  resize.observe(canvas);
  const scheme = window.matchMedia?.("(prefers-color-scheme: dark)");
  scheme?.addEventListener("change", render);

  render();
  // Autoplay only when the reader has not asked for reduced motion.
  if (!reducedMotion() && options.secondsPerFrame !== undefined) play();

  return {
    view,
    get index() {
      return index;
    },
    setRecording(r) {
      rec = r;
      goTo(Math.min(index, r.frames.length - 1));
    },
    goTo(i) {
      pause();
      goTo(i);
    },
    play,
    pause,
    destroy() {
      pause();
      resize.disconnect();
      scheme?.removeEventListener("change", render);
      root.remove();
    },
  };
}
